import {runFileScanBatch} from '../file-security';
import {test,after,before} from 'node:test';
import assert from 'node:assert/strict';
import {randomUUID} from 'node:crypto';
import {buildServer} from '../server';
import {pool} from '../db';
import {migrate} from '../migrate';
import {totp,can} from '../security';
let app:Awaited<ReturnType<typeof buildServer>>;
const suffix=randomUUID().slice(0,8),password='Local-validation-'+randomUUID();
const testAddress='127.0.'+parseInt(suffix.slice(0,2),16)+'.'+parseInt(suffix.slice(2,4),16);
const headers={'x-studio-client':'web',origin:'http://localhost:3000'};
async function request(method:string,url:string,body:unknown={},cookie='',remoteAddress=testAddress){return app.inject({method:method as 'GET'|'POST',url,remoteAddress,headers:{...headers,'content-type':'application/json',...(cookie?{cookie}:{})},...(method==='GET'?{}:{payload:JSON.stringify(body)})})}
async function register(name:string,remoteAddress=testAddress){const email=`${name}-${suffix}@example.test`;const created=await request('POST','/auth/register',{name,email,password,organization:name+' QA workspace'},'',remoteAddress);assert.equal(created.statusCode,201,created.body);const link=created.json().development_link;const token=new URL('http://localhost'+link).searchParams.get('token');assert.equal((await request('POST','/auth/token',{token},'',remoteAddress)).statusCode,200);const login=await request('POST','/auth/login',{email,password},'',remoteAddress);assert.equal(login.statusCode,200,login.body);const cookie=login.headers['set-cookie'] as string;const me=(await request('GET','/auth/me',{},cookie)).json().user;return {cookie,me,email}}
let adminSecret='';
let admin:Awaited<ReturnType<typeof register>>,one:typeof admin,two:typeof admin;
before(async()=>{if(!process.env.DATABASE_URL?.includes('anibish_qa'))throw new Error('Tests require a dedicated anibish_qa database.');await migrate();app=await buildServer();admin=await register('studio-admin');one=await register('customer-one');two=await register('customer-two');await pool.query('UPDATE users SET global_role=\'super_admin\' WHERE id=$1',[admin.me.id]);const blocked=await request('GET','/admin/services',{},admin.cookie);assert.equal(blocked.statusCode,403);const setup=(await request('POST','/auth/mfa/setup',{},admin.cookie)).json();adminSecret=setup.secret;assert.equal((await request('POST','/auth/mfa/verify',{code:totp(setup.secret)},admin.cookie)).statusCode,200)});
after(async()=>{await app?.close();await pool.end()});
test('CSRF protection, credentials, single-use tokens and revoked sessions',async()=>{assert.equal((await app.inject({method:'POST',url:'/auth/login',payload:{email:one.email,password}})).statusCode,403);assert.equal((await app.inject({method:'POST',url:'/auth/login',headers:{...headers,origin:'https://hostile.example'},payload:{email:one.email,password}})).statusCode,403);assert.equal((await request('POST','/auth/login',{email:one.email,password:'incorrect'})).statusCode,401);const recover=(await request('POST','/auth/recover',{email:two.email})).json();const token=new URL('http://localhost'+recover.development_link).searchParams.get('token');assert.equal((await request('POST','/auth/token',{token,password})).statusCode,200);assert.equal((await request('GET','/auth/me',{},two.cookie)).statusCode,401);assert.equal((await request('POST','/auth/token',{token,password})).statusCode,400);const login=await request('POST','/auth/login',{email:two.email,password});two.cookie=login.headers['set-cookie'] as string});
test('complete quote → order → sandbox payment → project → messages → revisions → approval → invoice → support',async()=>{const enquiry=await request('POST','/enquiries',{title:'QA knowledge assistant',email:one.email,brief:'A private document search experience with clear grounded citations.'},one.cookie);assert.equal(enquiry.statusCode,200,enquiry.body);const quoteResponse=await request('POST','/quotes',{org_id:one.me.org_id,lead_id:enquiry.json().record.id,title:'QA knowledge assistant',currency:'INR',lines:[{description:'Grounded retrieval prototype',quantity:1,unit_amount:500000}],terms:'Sandbox engagement. Source and documentation included.',status:'sent'},admin.cookie);assert.equal(quoteResponse.statusCode,200,quoteResponse.body);const quote=quoteResponse.json();assert.equal((await request('GET','/quotes',{},two.cookie)).json().some((q:{id:string})=>q.id===quote.id),false);assert.equal((await request('POST',`/quotes/${quote.id}/decision`,{decision:'accepted'},two.cookie)).statusCode,404);const accepts=await Promise.all([request('POST',`/quotes/${quote.id}/decision`,{decision:'accepted'},one.cookie),request('POST',`/quotes/${quote.id}/decision`,{decision:'accepted'},one.cookie)]);assert.equal(accepts[0].statusCode,200,accepts[0].body);assert.equal(accepts[0].json().order.id,accepts[1].json().order.id);const order=accepts[0].json().order;const project=(await request('GET','/projects',{},one.cookie)).json().find((p:{order_id:string})=>p.order_id===order.id);assert.ok(project);assert.equal((await request('GET','/projects/'+project.id,{},two.cookie)).statusCode,404);const key=randomUUID(),payment={order_id:order.id,amount:500000,idempotency_key:key};const payments=await Promise.all([request('POST','/payments/sandbox',payment,one.cookie),request('POST','/payments/sandbox',payment,one.cookie)]);assert.equal(payments[0].statusCode,200,payments[0].body);assert.equal(payments[0].json().id,payments[1].json().id);assert.equal((await request('POST','/payments/sandbox',{...payment,amount:499999},one.cookie)).statusCode,409);assert.equal((await request('POST','/payments/sandbox',{...payment,idempotency_key:randomUUID()},two.cookie)).statusCode,404);const m=(await request('GET','/milestones',{},one.cookie)).json().filter((m:{project_id:string})=>m.project_id===project.id);assert.equal(m.length,3);const task=await request('POST','/tasks',{project_id:project.id,title:'Internal evaluation cases',internal:true},admin.cookie);assert.equal(task.statusCode,200,task.body);assert.equal((await request('GET','/tasks',{},one.cookie)).json().some((t:{id:string})=>t.id===task.json().id),false);const thread=(await request('GET','/conversations',{},one.cookie)).json().find((c:{project_id:string})=>c.project_id===project.id);assert.equal((await request('POST',`/conversations/${thread.id}/messages`,{body:'Prototype is ready.'},admin.cookie)).statusCode,200);await request('POST',`/conversations/${thread.id}/messages`,{body:'Internal commercial note',internal:true},admin.cookie);assert.equal((await request('GET',`/conversations/${thread.id}/messages`,{},one.cookie)).json().length,1);assert.equal((await request('GET',`/conversations/${thread.id}/messages`,{},two.cookie)).statusCode,404);assert.equal((await request('POST',`/conversations/${thread.id}/messages`,{body:'Attempted internal note',internal:true},one.cookie)).statusCode,403);const d1=(await request('POST','/deliveries',{project_id:project.id,milestone_id:m[0].id,title:'Prototype v1',note:'Please review the source references.'},admin.cookie)).json();const revision=await request('POST',`/deliveries/${d1.id}/decision`,{decision:'revision_requested',note:'Please improve the source labels.'},one.cookie);assert.equal(revision.statusCode,200,revision.body);assert.equal((await request('POST',`/deliveries/${d1.id}/decision`,{decision:'approved'},one.cookie)).statusCode,409);const d2=(await request('POST','/deliveries',{project_id:project.id,milestone_id:m[0].id,title:'Prototype v2',note:'Source labels refined.'},admin.cookie)).json();assert.equal(d2.version,d1.version+1);assert.equal((await request('POST',`/deliveries/${d2.id}/decision`,{decision:'approved'},one.cookie)).statusCode,200);assert.ok((await request('GET',`/projects/${project.id}/progress`,{},one.cookie)).json().percent>0);const invoice=(await request('GET','/invoices',{},one.cookie)).json().find((i:{order_id:string})=>i.order_id===order.id);const pdf=await request('GET',`/invoices/${invoice.id}/pdf`,{},one.cookie);assert.equal(pdf.statusCode,200,pdf.body);assert.equal(pdf.rawPayload.subarray(0,4).toString(),'%PDF');assert.equal((await request('GET',`/invoices/${invoice.id}/pdf`,{},two.cookie)).statusCode,404);assert.equal((await request('POST','/tickets',{project_id:project.id,title:'Setup guidance',body:'Please clarify the local setup sequence.'},one.cookie)).statusCode,200);assert.equal((await request('POST','/tickets',{project_id:project.id,title:'Cross tenant ticket',body:'Not allowed.'},two.cookie)).statusCode,404);const db=await pool.query('SELECT count(*)::int AS count FROM payments WHERE order_id=$1',[order.id]);assert.equal(db.rows[0].count,1)});
test('database boundary rejects cross-organization project references',async()=>{const p=await request('POST','/projects',{title:'Tenant boundary test',org_id:one.me.org_id},admin.cookie);assert.equal(p.statusCode,200,p.body);await assert.rejects(pool.query('INSERT INTO tasks(org_id,project_id,title) VALUES($1,$2,$3)',[two.me.org_id,p.json().id,'Must fail']),/foreign key/)});
test('member roles cannot grant themselves administrative privileges',async()=>{assert.equal((await request('GET','/admin/audit',{},one.cookie)).statusCode,403);assert.equal((await request('PATCH','/auth/profile',{name:'Owner',global_role:'super_admin'},one.cookie)).statusCode,400);assert.equal(can('finance_manager','payments',true),true);assert.equal(can('finance_manager','tasks',true),false);assert.equal(can('support_agent','services',true),false);assert.equal(can('developer','tasks',true),true)});
async function scanForTest(kind:string,id:string){const rows=(await pool.query('SELECT id FROM file_scan_records WHERE source_kind=$1 AND source_id=$2',[kind,id])).rows;assert.equal(rows.length,1);await runFileScanBatch(async()=>({status:'clean',reason:'',version:'ClamAV QA/1/'+new Date().toUTCString(),signatureAt:new Date()}),[rows[0].id]);}
test('files are stored privately, downloaded by owner and denied to another tenant',async()=>{const boundary='anibish-test-boundary';const content=`--${boundary}\r\nContent-Disposition: form-data; name="file"; filename="handover.txt"\r\nContent-Type: text/plain\r\n\r\nA private handover note.\r\n--${boundary}--\r\n`;const upload=await app.inject({method:'POST',url:'/files',headers:{...headers,cookie:one.cookie,'content-type':'multipart/form-data; boundary='+boundary},payload:content});assert.equal(upload.statusCode,200,upload.body);const id=upload.json().id;assert.equal((await request('GET','/files/'+id+'/download',{},one.cookie)).statusCode,409);await scanForTest('file',id);const download=await request('GET','/files/'+id+'/download',{},one.cookie);assert.equal(download.statusCode,200);assert.equal(download.body,'A private handover note.');assert.equal((await request('GET','/files/'+id+'/download',{},two.cookie)).statusCode,404);assert.equal((await request('GET','/files/'+id+'/download')).statusCode,401)});
test('services require explicit price approval; fixed checkout replays safely',async()=>{const response=await request('POST','/admin/services',{slug:'qa-service-'+suffix,title:'QA approved sandbox service',category:'Engineering',description:'A scoped sandbox service for integration verification.',pricing_model:'fixed',amount:100000,currency:'INR',status:'published',data:{placeholder:true,price_approved:false}},admin.cookie);assert.equal(response.statusCode,200,response.body);const service=response.json();const payload={service_id:service.id,accepted_terms:true,idempotency_key:randomUUID()};assert.equal((await request('POST','/checkout',payload,one.cookie)).statusCode,409);await request('PATCH','/admin/services/'+service.id,{slug:service.slug,title:service.title,category:service.category,description:service.description,pricing_model:'fixed',amount:100000,currency:'INR',status:'published',data:{placeholder:false,price_approved:true}},admin.cookie);const a=await request('POST','/checkout',payload,one.cookie),b=await request('POST','/checkout',payload,one.cookie);assert.equal(a.statusCode,200,a.body);assert.equal(a.json().order.id,b.json().order.id);for(const template of ['order_confirmation','project_created'])assert.equal((await pool.query("SELECT count(*) FROM outbox WHERE recipient=$1 AND template=$2 AND payload->>'body'=$3",[one.email,template,service.title])).rows[0].count,'1',template)});
test('itemized invoices finalize sequentially, remain immutable, and isolate customers',async()=>{const order=(await pool.query("INSERT INTO orders(org_id,title,currency,total) VALUES($1,'Advanced invoice QA','INR',200000) RETURNING *",[one.me.org_id])).rows[0];const payload={order_id:order.id,lines:[{description:'Architecture',quantity:2,unit_amount:50000}],tax_rate_bps:1800,discount:10000,deposit_applied:0,due_date:'2026-01-01',kind:'milestone'};const a=await request('POST','/finance/invoices',payload,admin.cookie);assert.equal(a.statusCode,200,a.body);assert.equal(Number(a.json().total),106200);const second=await request('POST','/finance/invoices',{...payload,lines:[{description:'Review',quantity:1,unit_amount:25000}],tax_rate_bps:0,discount:0},admin.cookie);const finals=await Promise.all([request('POST','/finance/invoices/'+a.json().id+'/finalize',{},admin.cookie),request('POST','/finance/invoices/'+second.json().id+'/finalize',{},admin.cookie)]);assert.equal(finals[0].statusCode,200,finals[0].body);assert.notEqual(finals[0].json().number,finals[1].json().number);assert.match(finals[0].json().number,/^AB-\d{4}-\d{6}$/);assert.equal((await request('PATCH','/finance/invoices/'+a.json().id,payload,admin.cookie)).statusCode,409);await assert.rejects(pool.query('UPDATE invoices SET total=1 WHERE id=$1',[a.json().id]),/immutable/);await assert.rejects(pool.query("UPDATE invoices SET due_date='2030-01-01' WHERE id=$1",[a.json().id]),/immutable/);const pdf=await request('GET','/invoices/'+a.json().id+'/pdf',{},one.cookie);assert.equal(pdf.statusCode,200);assert.equal(pdf.rawPayload.subarray(0,4).toString(),'%PDF');assert.equal((await request('GET','/finance/invoices/'+a.json().id+'/history',{},two.cookie)).statusCode,404);const history=await request('GET','/finance/invoices/'+a.json().id+'/history',{},one.cookie);assert.ok(history.json().some((h:{event:string})=>h.event==='finalized'));const report=await request('GET','/finance/reports',{},admin.cookie);assert.equal(report.statusCode,200);assert.equal((await request('GET','/finance/reports',{},one.cookie)).statusCode,403)});
test('raw sandbox callbacks authenticate bytes, reject tampering and replay safely',async()=>{const {createHmac}=await import('node:crypto');process.env.SANDBOX_PAYMENT_SECRET='qa-signing-secret-'+suffix+'-'.repeat(32);const order=(await pool.query("INSERT INTO orders(org_id,title,currency,total) VALUES($1,'Signed callback QA','INR',50000) RETURNING *",[one.me.org_id])).rows[0];const payload=JSON.stringify({event_id:'event-'+randomUUID(),order_id:order.id,amount:50000,currency:'INR'});const signature=createHmac('sha256',process.env.SANDBOX_PAYMENT_SECRET).update(payload).digest('hex');const inject=(sig:string,body=payload)=>app.inject({method:'POST',url:'/payments/webhook/sandbox',headers:{'content-type':'application/json','x-anibish-signature':sig},payload:body});assert.equal((await inject('0'.repeat(64))).statusCode,401);const first=await inject(signature);assert.equal(first.statusCode,200,first.body);assert.equal((await inject(signature)).json().replayed,true);assert.equal((await inject(signature,payload+' ')).statusCode,401);assert.equal(Number((await pool.query('SELECT paid FROM orders WHERE id=$1',[order.id])).rows[0].paid),50000)});
test('manual sandbox transfer verification and recurring bills are idempotent',async()=>{const {runRecurringBilling}=await import('../worker');const order=(await pool.query("INSERT INTO orders(org_id,title,currency,total) VALUES($1,'Retainer QA','INR',50000) RETURNING *",[one.me.org_id])).rows[0];const transfer=await request('POST','/finance/manual-transfers',{order_id:order.id,amount:10000,reference:'QA-'+randomUUID(),note:'Sandbox verification only'},admin.cookie);assert.equal(transfer.statusCode,200,transfer.body);assert.equal((await request('POST','/finance/manual-transfers/'+transfer.json().id+'/verify',{},one.cookie)).statusCode,403);assert.equal((await request('POST','/finance/manual-transfers/'+transfer.json().id+'/verify',{},admin.cookie)).statusCode,200);assert.equal((await request('POST','/finance/manual-transfers/'+transfer.json().id+'/verify',{},admin.cookie)).statusCode,200);assert.equal(Number((await pool.query('SELECT paid FROM orders WHERE id=$1',[order.id])).rows[0].paid),10000);const [{today}]=(await pool.query("SELECT CURRENT_DATE::text AS today")).rows;const agreement=await request('POST','/finance/agreements',{order_id:order.id,title:'Maintenance QA',amount:5000,next_bill_date:today,kind:'maintenance'},admin.cookie);assert.equal(agreement.statusCode,200,agreement.body);await runRecurringBilling();await runRecurringBilling();assert.equal(Number((await pool.query('SELECT count(*) AS n FROM recurring_runs WHERE agreement_id=$1',[agreement.json().id])).rows[0].n),1);assert.equal((await request('POST','/finance/agreements/'+agreement.json().id+'/cancel',{reason:'QA cancellation request'},two.cookie)).statusCode,404)});
test('CMS drafts, published snapshots, revision conflicts and evidence checks work',async()=>{const payload={slug:'qa-content-'+suffix,title:'CMS QA',kind:'review',content:{body:'An authentic source excerpt.',evidence_attested:false},seo:{title:'QA title',canonical:'https://anibish.com/qa-content-'+suffix}};const created=await request('POST','/cms/pages',payload,admin.cookie);assert.equal(created.statusCode,200,created.body);const id=created.json().id;assert.equal((await request('GET','/cms/pages/'+id+'/preview',{},one.cookie)).statusCode,403);assert.equal((await request('POST','/cms/pages/'+id+'/publish',{expected_revision:1},admin.cookie)).statusCode,400);const saved=await request('PATCH','/cms/pages/'+id,{...payload,expected_revision:1,content:{body:'Approved excerpt.',evidence_attested:true}},admin.cookie);assert.equal(saved.statusCode,200,saved.body);assert.equal((await request('POST','/cms/pages/'+id+'/publish',{expected_revision:1},admin.cookie)).statusCode,409);assert.equal((await request('POST','/cms/pages/'+id+'/publish',{expected_revision:2},admin.cookie)).statusCode,200);let site=(await request('GET','/public/site')).json();assert.equal(site.pages.find((p:{slug:string})=>p.slug===payload.slug).content.body,'Approved excerpt.');await request('PATCH','/cms/pages/'+id,{...payload,expected_revision:2,content:{body:'Unpublished secret draft.',evidence_attested:true}},admin.cookie);site=(await request('GET','/public/site')).json();assert.equal(site.pages.find((p:{slug:string})=>p.slug===payload.slug).content.body,'Approved excerpt.');assert.equal((await request('POST','/cms/pages/'+id+'/archive',{},admin.cookie)).statusCode,200);assert.equal((await request('GET','/public/site')).json().pages.some((p:{slug:string})=>p.slug===payload.slug),false)});
test('public production gate leaves enquiries open and privileged endpoints closed',async()=>{const previous={NODE_ENV:process.env.NODE_ENV,PUBLIC_ORIGIN:process.env.PUBLIC_ORIGIN,LAUNCH_STAGE:process.env.LAUNCH_STAGE,MFA_ENCRYPTION_KEY:process.env.MFA_ENCRYPTION_KEY,REDIS_URL:process.env.REDIS_URL,PAYMENT_MODE:process.env.PAYMENT_MODE};process.env.NODE_ENV='production';process.env.PUBLIC_ORIGIN='https://anibish.com';process.env.LAUNCH_STAGE='public';process.env.MFA_ENCRYPTION_KEY='01'.repeat(32);process.env.REDIS_URL='redis://127.0.0.1:56368';process.env.PAYMENT_MODE='sandbox';const publicApp=await buildServer();try{assert.equal((await publicApp.inject({method:'GET',url:'/orders'})).statusCode,503);assert.equal((await publicApp.inject({method:'POST',url:'/auth/register',headers:{'x-studio-client':'web'},payload:{name:'Disabled'}})).statusCode,503);const enquiry=await publicApp.inject({method:'POST',url:'/enquiries',headers:{'x-studio-client':'web',origin:'https://anibish.com'},payload:{title:'Production gate smoke',email:'qa-launch@example.test',brief:'Disposable test enquiry for production public launch readiness.'}});assert.equal(enquiry.statusCode,200,enquiry.body);assert.ok(enquiry.json().reference);assert.equal(enquiry.body.includes('development_link'),false);assert.equal((await publicApp.inject({method:'POST',url:'/enquiries',headers:{'x-studio-client':'web',origin:'https://hostile.example'},payload:{}})).statusCode,403)}finally{await publicApp.close();for(const [k,v]of Object.entries(previous)){if(v===undefined)delete process.env[k];else process.env[k]=v}}});
test('email outbox uses stable jobs, records deliveries, and retries without secret payload logs',async()=>{const {runOutboxBatch}=await import('../worker');const [job]=(await pool.query("INSERT INTO outbox(recipient,template,payload,dedupe_key) VALUES('qa-mail@example.test','new_message',$1,$2) RETURNING id",[JSON.stringify({body:'A local transport test.'}),'mail-qa-'+randomUUID()])).rows;let calls=0;const transport={sendMail:async()=>{calls++;return {messageId:'qa-message-id'}}} as unknown as NonNullable<Parameters<typeof runOutboxBatch>[0]>;await runOutboxBatch(transport,job.id);await runOutboxBatch(transport,job.id);assert.equal(calls,1);const [sent]=(await pool.query('SELECT status,delivery_id FROM outbox WHERE id=$1',[job.id])).rows;assert.equal(sent.status,'sent');assert.equal(sent.delivery_id,'qa-message-id');const [failed]=(await pool.query("INSERT INTO outbox(recipient,template,payload) VALUES('qa-mail@example.test','new_message','{}') RETURNING id")).rows;const broken={sendMail:async()=>{throw Object.assign(new Error('Do not log SMTP passwords or payload'),{code:'EAUTH'})}} as unknown as NonNullable<Parameters<typeof runOutboxBatch>[0]>;await runOutboxBatch(broken,failed.id);const [retried]=(await pool.query('SELECT status,attempts,last_error FROM outbox WHERE id=$1',[failed.id])).rows;assert.equal(retried.status,'retry');assert.equal(retried.attempts,1);assert.equal(retried.last_error,'EAUTH')});
test('persistent sign-in lockout survives a new API process instance',async()=>{const email='lockout-'+suffix+'@example.test';const payload={email,password:'Incorrect-password-for-lockout'};const attempt=(target:typeof app)=>target.inject({method:'POST',url:'/auth/login',remoteAddress:'127.1.'+parseInt(suffix.slice(0,2),16)+'.'+parseInt(suffix.slice(2,4),16),headers,payload});for(let n=0;n<5;n++)assert.equal((await attempt(app)).statusCode,401);assert.equal((await attempt(app)).statusCode,429);const restarted=await buildServer();try{assert.equal((await attempt(restarted)).statusCode,429)}finally{await restarted.close()}});
test('project dependencies reject cycles and cross-project links; private time and attachments isolate tenants',async()=>{const makeProject=async(title:string,org_id:string)=>(await request('POST','/projects',{title,org_id},admin.cookie)).json();const p=await makeProject('Dependency QA',one.me.org_id),other=await makeProject('Other tenant QA',two.me.org_id);const task=async(project_id:string,title:string)=>(await request('POST','/tasks',{project_id,title},admin.cookie)).json();const a=await task(p.id,'First task'),b=await task(p.id,'Second task'),foreign=await task(other.id,'Foreign task');assert.equal((await request('POST','/tasks/'+a.id+'/dependencies',{depends_on:b.id},admin.cookie)).statusCode,200);assert.equal((await request('POST','/tasks/'+b.id+'/dependencies',{depends_on:a.id},admin.cookie)).statusCode,409);assert.equal((await request('POST','/tasks/'+a.id+'/dependencies',{depends_on:foreign.id},admin.cookie)).statusCode,400);assert.equal((await request('GET','/projects/'+p.id+'/dependencies',{},two.cookie)).statusCode,404);assert.equal((await request('POST','/projects/'+p.id+'/time',{minutes:45,note:'Dependency evaluation',work_date:'2026-11-16'},admin.cookie)).statusCode,200);assert.equal((await request('GET','/projects/'+p.id+'/time',{},one.cookie)).statusCode,403);const t=(await request('POST','/conversations',{title:'Attachment QA',project_id:p.id},admin.cookie)).json();const foreignFile=(await pool.query("INSERT INTO files(org_id,user_id,name,mime,size,storage_key,sha256) VALUES($1,$2,'foreign.txt','text/plain',1,$3,'qa') RETURNING id",[two.me.org_id,two.me.id,randomUUID()])).rows[0];assert.equal((await request('POST','/conversations/'+t.id+'/messages',{body:'Do not disclose foreign attachment',file_ids:[foreignFile.id]},admin.cookie)).statusCode,400);const note=(await request('POST','/conversations/'+t.id+'/messages',{body:'Internal-only dependency decision',internal:true},admin.cookie)).json();assert.equal((await request('POST','/conversations/'+t.id+'/messages',{body:'Public reply must not reference private text',reply_to:note.id},admin.cookie)).statusCode,400);assert.equal((await request('POST','/conversations/'+t.id+'/messages',{body:'Visible dependency update'},admin.cookie)).statusCode,200);const unread=await request('GET','/conversations/unread',{},one.cookie);assert.equal(unread.statusCode,200,unread.body);assert.equal(unread.json().find((r:{conversation_id:string})=>r.conversation_id===t.id).unread,1);assert.equal((await request('GET','/messages/search?q=Internal-only',{},one.cookie)).json().length,0);await request('GET','/conversations/'+t.id+'/messages',{},one.cookie);assert.equal((await request('GET','/conversations/unread',{},one.cookie)).json().some((r:{conversation_id:string})=>r.conversation_id===t.id),false)});
test('CMS gallery approval is enforced and redirect cycles are rejected',async()=>{const payload={slug:'qa-gallery-'+suffix,title:'QA gallery',kind:'page',content:{blocks:[{title:'Private evidence',media_id:randomUUID()}]}};const page=(await request('POST','/cms/pages',payload,admin.cookie)).json();assert.equal((await request('POST','/cms/pages/'+page.id+'/publish',{expected_revision:1},admin.cookie)).statusCode,400);const a='/qa-redirect-a-'+suffix,b='/qa-redirect-b-'+suffix;assert.equal((await request('POST','/cms/redirects',{source:a,destination:b,status:301},admin.cookie)).statusCode,200);assert.equal((await request('POST','/cms/redirects',{source:b,destination:a,status:301},admin.cookie)).statusCode,409);const publicRedirects=await request('GET','/public/redirects');assert.equal(publicRedirects.statusCode,200);assert.equal(publicRedirects.json().find((r:{source:string})=>r.source===a).status,301)});
test('refund recording creates one scoped currency-labelled credit note',async()=>{const order=(await pool.query("INSERT INTO orders(org_id,title,currency,total,paid) VALUES($1,'Refund QA','USD',10000,10000) RETURNING id",[one.me.org_id])).rows[0];const payment=(await pool.query("INSERT INTO payments(org_id,order_id,amount,currency,provider,provider_ref,idempotency_key) VALUES($1,$2,10000,'USD','sandbox',$3,$3) RETURNING id",[one.me.org_id,order.id,randomUUID()])).rows[0];const refund=await request('POST','/refunds',{payment_id:payment.id,amount:2500,reason:'Sandbox refund verification.'},one.cookie);assert.equal(refund.statusCode,200,refund.body);const id=refund.json().id;assert.equal((await request('POST','/finance/refunds/'+id+'/record',{},two.cookie)).statusCode,403);assert.equal((await request('POST','/finance/refunds/'+id+'/record',{},admin.cookie)).statusCode,200);assert.equal((await request('POST','/finance/refunds/'+id+'/record',{},admin.cookie)).statusCode,200);const credits=(await request('GET','/finance/credits',{},one.cookie)).json().filter((c:{payment_id:string})=>c.payment_id===payment.id);assert.equal(credits.length,1);assert.equal(credits[0].currency,'USD');assert.equal((await request('GET','/finance/credits',{},two.cookie)).json().some((c:{payment_id:string})=>c.payment_id===payment.id),false)});
test('recurring month-end anchors and renewal notices preserve preferences and idempotence',async()=>{const {runRenewalNotices}=await import('../worker');const [dates]=(await pool.query("SELECT next_billing_date('2027-01-31',1,31)::text AS feb,next_billing_date('2027-02-28',1,31)::text AS mar")).rows;assert.equal(dates.feb,'2027-02-28');assert.equal(dates.mar,'2027-03-31');const order=(await pool.query("INSERT INTO orders(org_id,title,currency,total) VALUES($1,'Renewal notice QA','INR',5000) RETURNING id",[one.me.org_id])).rows[0];const [agreement]=(await pool.query("INSERT INTO billing_agreements(org_id,order_id,title,amount,currency,next_bill_date) VALUES($1,$2,'Upcoming maintenance',5000,'INR',CURRENT_DATE+1) RETURNING id",[one.me.org_id,order.id])).rows;await pool.query('UPDATE users SET preferences=$1 WHERE id=$2',[JSON.stringify({email_updates:false}),one.me.id]);await runRenewalNotices();await runRenewalNotices();assert.equal(Number((await pool.query('SELECT count(*) FROM billing_notice_events WHERE agreement_id=$1',[agreement.id])).rows[0].count),1);assert.equal(Number((await pool.query("SELECT count(*) FROM outbox WHERE dedupe_key LIKE $1",['upcoming:'+agreement.id+':%'])).rows[0].count),0);await pool.query("UPDATE users SET preferences='{}' WHERE id=$1",[one.me.id])});
test('internal attachments remain private and mismatched image payloads stay quarantined',async()=>{const boundary='private-file-'+suffix;const payload=`--${boundary}\r\nContent-Disposition: form-data; name="org_id"\r\n\r\n${one.me.org_id}\r\n--${boundary}\r\nContent-Disposition: form-data; name="internal"\r\n\r\ntrue\r\n--${boundary}\r\nContent-Disposition: form-data; name="file"; filename="internal-note.txt"\r\nContent-Type: text/plain\r\n\r\nPrivate studio-only attachment.\r\n--${boundary}--\r\n`;const uploaded=await app.inject({method:'POST',url:'/files',headers:{...headers,cookie:admin.cookie,'content-type':'multipart/form-data; boundary='+boundary},payload});assert.equal(uploaded.statusCode,200,uploaded.body);const id=uploaded.json().id;assert.equal((await request('GET','/files/'+id+'/download',{},one.cookie)).statusCode,404);assert.equal((await request('GET','/files',{},one.cookie)).json().some((f:{id:string})=>f.id===id),false);assert.equal((await request('POST','/cms/media/'+id+'/approve',{publication_rights_confirmed:true,approved:true},admin.cookie)).statusCode,400);const thread=(await request('POST','/conversations',{title:'Internal attachment QA',org_id:one.me.org_id},admin.cookie)).json();assert.equal((await request('POST','/conversations/'+thread.id+'/messages',{body:'Internal attachment',internal:true,file_ids:[id]},admin.cookie)).statusCode,200);assert.equal((await request('POST','/conversations/'+thread.id+'/messages',{body:'Do not publish internal attachment',file_ids:[id]},admin.cookie)).statusCode,400);const forged=payload.replace('internal-note.txt','forged.png').replace('Content-Type: text/plain','Content-Type: image/png');const forgedUpload=await app.inject({method:'POST',url:'/files',headers:{...headers,cookie:admin.cookie,'content-type':'multipart/form-data; boundary='+boundary},payload:forged});assert.equal(forgedUpload.statusCode,200);assert.equal((await request('GET','/files/'+forgedUpload.json().id+'/download',{},admin.cookie)).statusCode,423)});
test('support replies preserve privacy and measure only customer-visible staff responses',async()=>{const ticket=(await request('POST','/tickets',{title:'Response reporting QA',body:'Please confirm the delivery support process.'},one.cookie)).json();assert.equal((await request('POST','/tickets/'+ticket.id+'/replies',{body:'Private studio investigation',internal:true},admin.cookie)).statusCode,200);let row=(await request('GET','/tickets/'+ticket.id,{},one.cookie)).json();assert.equal(row.first_response_at,null);assert.equal((await request('GET','/tickets/'+ticket.id+'/replies',{},one.cookie)).json().length,0);assert.equal((await request('GET','/tickets/'+ticket.id+'/replies',{},two.cookie)).statusCode,404);assert.equal((await request('POST','/tickets/'+ticket.id+'/replies',{body:'The requested support details are available.'},admin.cookie)).statusCode,200);row=(await request('GET','/tickets/'+ticket.id,{},one.cookie)).json();assert.ok(row.first_response_at);const report=await request('GET','/reports/operations',{},admin.cookie);assert.equal(report.statusCode,200,report.body);assert.ok(report.json().support.find((t:{id:string})=>t.id===ticket.id).first_response_minutes!=null);assert.equal((await request('GET','/reports/operations',{},one.cookie)).statusCode,403);assert.equal((await request('GET','/reports/export',{},admin.cookie)).statusCode,200)});
test('final project acceptance requires approved delivery and completed milestones',async()=>{const project=(await request('POST','/projects',{title:'Final handover QA',org_id:one.me.org_id},admin.cookie)).json();assert.equal((await request('POST','/projects/'+project.id+'/handover',{note:'Reviewed.'},one.cookie)).statusCode,409);const milestone=(await request('POST','/milestones',{title:'Final milestone',project_id:project.id},admin.cookie)).json();const delivery=(await request('POST','/deliveries',{title:'Final package',project_id:project.id,milestone_id:milestone.id,note:'Documented handover package.'},admin.cookie)).json();assert.equal((await request('POST','/projects/'+project.id+'/handover',{note:'Reviewed.'},two.cookie)).statusCode,404);assert.equal((await request('POST','/deliveries/'+delivery.id+'/decision',{decision:'approved',note:'Scope reviewed.'},one.cookie)).statusCode,200);assert.equal((await request('POST','/projects/'+project.id+'/handover',{note:'Final handover accepted.'},one.cookie)).statusCode,200);assert.equal((await request('POST','/projects/'+project.id+'/handover',{note:'Duplicate acceptance.'},one.cookie)).statusCode,409);assert.equal((await request('GET','/projects/'+project.id,{},one.cookie)).json().status,'completed')});
test('admin-only production stage requires MFA, secure cookies, and denies customer access',async()=>{
 const keys=['NODE_ENV','PUBLIC_ORIGIN','LAUNCH_STAGE','MFA_ENCRYPTION_KEY','PAYMENT_MODE','REDIS_URL','SANDBOX_PAYMENT_SECRET'];
 const previous=Object.fromEntries(keys.map(k=>[k,process.env[k]]));
 const [{mfa_secret:originalSecret}]=(await pool.query('SELECT mfa_secret FROM users WHERE id=$1',[admin.me.id])).rows;
 let guarded:Awaited<ReturnType<typeof buildServer>>|undefined;
 try{
  process.env.NODE_ENV='production';process.env.PUBLIC_ORIGIN='https://anibish.com';process.env.LAUNCH_STAGE='admin';process.env.MFA_ENCRYPTION_KEY='02'.repeat(32);process.env.PAYMENT_MODE='sandbox';
  process.env.REDIS_URL||='redis://127.0.0.1:56368';process.env.SANDBOX_PAYMENT_SECRET||='qa-'+randomUUID()+randomUUID();
  const {mfaSecret,encryptSecret}=await import('../security');const secret=mfaSecret();
  await pool.query('UPDATE users SET mfa_secret=$1 WHERE id=$2',[encryptSecret(secret),admin.me.id]);
  const instance=await buildServer();guarded=instance;
  const call=(payload:Record<string,string>)=>instance.inject({method:'POST',url:'/auth/login',remoteAddress:'127.2.'+parseInt(suffix.slice(0,2),16)+'.'+parseInt(suffix.slice(2,4),16),headers:{'x-studio-client':'web',origin:'https://anibish.com'},payload});
  assert.equal((await call({email:admin.email,password})).statusCode,403);
  const signed=await call({email:admin.email,password,code:totp(secret)});assert.equal(signed.statusCode,200,signed.body);
  assert.match(String(signed.headers['set-cookie']),/Secure/);assert.match(String(signed.headers['set-cookie']),/HttpOnly/);
  assert.equal((await call({email:one.email,password})).statusCode,403);
  assert.equal((await instance.inject({method:'GET',url:'/projects',headers:{cookie:one.cookie}})).statusCode,403);
  assert.equal((await instance.inject({method:'POST',url:'/auth/register'})).statusCode,503);
  assert.equal((await instance.inject({method:'GET',url:'/admin/services',headers:{cookie:String(signed.headers['set-cookie'])}})).statusCode,200);
  assert.deepEqual((await instance.inject({method:'GET',url:'/public/site'})).json().features,{admin:true,customer:false});
 }finally{
  await guarded?.close();await pool.query('UPDATE users SET mfa_secret=$1 WHERE id=$2',[originalSecret,admin.me.id]);
  for(const [key,value]of Object.entries(previous)){if(value===undefined)delete process.env[key];else process.env[key]=value}
 }
});
test('notification preferences persist and suppress optional customer email updates',async()=>{const update=await request('PATCH','/auth/profile',{name:'QA customer with preferences',preferences:{email_updates:false}},one.cookie);assert.equal(update.statusCode,200,update.body);assert.equal((await request('GET','/auth/me',{},one.cookie)).json().user.preferences.email_updates,false);const before=Number((await pool.query('SELECT count(*) FROM outbox WHERE recipient=$1',[one.email])).rows[0].count);await request('POST','/tickets',{title:'Preference-aware ticket',body:'A support request with email updates disabled.'},one.cookie);const after=Number((await pool.query('SELECT count(*) FROM outbox WHERE recipient=$1',[one.email])).rows[0].count);assert.equal(after,before);await request('PATCH','/auth/profile',{name:'QA customer',preferences:{email_updates:true}},one.cookie)});
test('private original evidence requires studio access and a matching source hash',async()=>{const {mkdtemp,writeFile,rm}=await import('node:fs/promises'),{tmpdir}=await import('node:os'),{join}=await import('node:path'),{createHash}=await import('node:crypto');const directory=await mkdtemp(join(tmpdir(),'anibish-evidence-qa-')),previous=process.env.EVIDENCE_DIR;process.env.EVIDENCE_DIR=directory;const bytes=Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aFksAAAAASUVORK5CYII=','base64');await writeFile(join(directory,'qa.png'),bytes);const [asset]=(await pool.query("INSERT INTO assets(source_path,source_hash,metadata) VALUES($1,$2,'{}') RETURNING id",['qa-'+suffix+'/qa.png',createHash('sha256').update(bytes).digest('hex')+'-'+suffix])).rows;await pool.query('UPDATE assets SET source_hash=$1 WHERE id=$2',[createHash('sha256').update(bytes).digest('hex'),asset.id]);try{assert.equal((await request('GET','/admin/assets/'+asset.id+'/evidence')).statusCode,401);assert.equal((await request('GET','/admin/assets/'+asset.id+'/evidence',{},one.cookie)).statusCode,403);const original=await request('GET','/admin/assets/'+asset.id+'/evidence',{},admin.cookie);assert.equal(original.statusCode,200,original.body);assert.equal(original.rawPayload.equals(bytes),true);await writeFile(join(directory,'qa.png'),'tampered evidence');assert.equal((await request('GET','/admin/assets/'+asset.id+'/evidence',{},admin.cookie)).statusCode,409)}finally{await pool.query('DELETE FROM assets WHERE id=$1',[asset.id]);await rm(directory,{recursive:true,force:true});if(previous===undefined)delete process.env.EVIDENCE_DIR;else process.env.EVIDENCE_DIR=previous}});

test('service editor round-trips the canonical pricing model through create, read, edit and archive',async()=>{const payload={slug:'qa-editor-'+randomUUID(),title:'QA service editor round trip',category:'QA',description:'An unpublished disposable service for editor verification.',pricing_model:'quote',amount:0,currency:'INR',status:'draft',data:{placeholder:true,price_approved:false}};const created=await request('POST','/admin/services',payload,admin.cookie);assert.equal(created.statusCode,200,created.body);const id=created.json().id;const read=async()=>(await request('GET','/admin/services',{},admin.cookie)).json().find((s:{id:string})=>s.id===id);assert.equal((await read()).pricing_model,'quote');assert.equal((await read()).pricingModel,undefined);const updated=await request('PATCH','/admin/services/'+id,{...payload,description:'Updated unpublished disposable service.'},admin.cookie);assert.equal(updated.statusCode,200,updated.body);assert.equal((await read()).pricing_model,'quote');assert.equal((await read()).description,'Updated unpublished disposable service.');assert.equal((await request('DELETE','/admin/services/'+id,{},admin.cookie)).statusCode,200);assert.equal((await read()).status,'archived');assert.equal((await request('GET','/services')).json().some((s:{id:string})=>s.id===id),false)});
test('legal drafts are owner-only, sanitized, versioned and accepted immutably',async()=>{
 const {cleanLegal,acceptLegal}=await import('../legal');assert.doesNotMatch(cleanLegal('<script>alert(1)</script><p onclick="evil()">Safe</p><a href="javascript:evil()">Link</a>'),/script|onclick|javascript/);
 assert.equal((await request('GET','/legal',{},one.cookie)).statusCode,403);
 const versions:Record<string,string>={};
 for(const policy of ['privacy','terms']){const drafts=(await request('GET','/legal',{},admin.cookie)).json().drafts;const d=drafts.find((r:{policy:string})=>r.policy===policy);const saved=await request('PUT','/legal/'+policy,{revision:d.revision,effective_date:'2026-01-01',html:'<h1>QA policy</h1><p>'+('Reviewed testing content. '.repeat(10))+'</p><script>unsafe()</script>'},admin.cookie);assert.equal(saved.statusCode,200,saved.body);assert.doesNotMatch(saved.json().html,/script|unsafe/);assert.equal((await request('POST','/legal/'+policy+'/publish',{revision:saved.json().revision,material:true},admin.cookie)).statusCode,400);const published=await request('POST','/legal/'+policy+'/publish',{revision:saved.json().revision,material:true,owner_legal_approval:true},admin.cookie);assert.equal(published.statusCode,200,published.body);versions[policy]=published.json().id;await assert.rejects(pool.query("UPDATE legal_versions SET html='changed' WHERE id=$1",[versions[policy]]),/immutable/)}
 const prev=process.env.NODE_ENV;process.env.NODE_ENV='production';const db=await pool.connect();try{await db.query('BEGIN');await assert.rejects(acceptLegal(db,{},one.me.id,'registration'));await db.query('ROLLBACK');await db.query('BEGIN');await acceptLegal(db,{legal_acceptance:{accepted:true,...versions}},one.me.id,'registration');await db.query('COMMIT');const consent=(await pool.query('SELECT id FROM legal_consents WHERE user_id=$1',[one.me.id])).rows;assert.equal(consent.length,2);await assert.rejects(pool.query('DELETE FROM legal_consents WHERE id=$1',[consent[0].id]),/immutable/)}finally{await db.query('ROLLBACK');db.release();if(prev===undefined)delete process.env.NODE_ENV;else process.env.NODE_ENV=prev}
});
test('private email cache, attachments and drafts require MFA Super Admin',async()=>{assert.equal((await request('GET','/email/accounts',{},one.cookie)).statusCode,403);const accounts=await request('GET','/email/accounts',{},admin.cookie);assert.equal(accounts.statusCode,200,accounts.body);assert.equal(accounts.json().length,2);const [m]=(await pool.query("INSERT INTO mail_messages(mailbox,folder,uidvalidity,uid,subject,body_text) VALUES('info','INBOX',$1,1,'Private QA email','Private QA body') RETURNING id",[randomUUID()])).rows;const [f]=(await pool.query("INSERT INTO mail_attachments(message_id,position,name,content,mime) VALUES($1,0,'qa.txt',$2,'text/plain') RETURNING id",[m.id,Buffer.from('QA attachment')])).rows;assert.equal((await request('GET','/email/messages/'+m.id,{},one.cookie)).statusCode,403);assert.equal((await request('GET','/email/attachments/'+f.id,{},two.cookie)).statusCode,403);const viewed=await request('GET','/email/messages/'+m.id,{},admin.cookie);assert.equal(viewed.statusCode,200,viewed.body);assert.equal(viewed.json().body_text,'Private QA body');assert.equal((await request('GET','/email/attachments/'+f.id,{},admin.cookie)).statusCode,409);await scanForTest('mail_attachment',f.id);const download=await request('GET','/email/attachments/'+f.id,{},admin.cookie);assert.equal(download.statusCode,200);assert.match(String(download.headers['content-disposition']),/^attachment/);const draft=await request('POST','/email/drafts',{mailbox:'mail',recipient:'qa@example.test',subject:'QA unsent draft',body:'Never send.'},admin.cookie);assert.equal(draft.statusCode,200,draft.body);assert.ok((await request('GET','/email/drafts',{},admin.cookie)).json().some((d:{id:string})=>d.id===draft.json().id))});

