test('private composition preserves cc and attachments, bounds payloads, and isolates signatures',async()=>{const extras={cc:['second@example.test'],attachments:[{name:'requirements.txt',base64:Buffer.from('Private QA attachment').toString('base64')}]};const draft=await request('POST','/email/drafts',{mailbox:'mail',recipient:'qa@example.test',subject:'Private composition QA',body:'Never send this QA draft.',extras},admin.cookie);assert.equal(draft.statusCode,200,draft.body);assert.deepEqual(draft.json().extras,extras);const drafts=(await request('GET','/email/drafts',{},admin.cookie)).json();assert.ok(drafts.find((d:{id:string})=>d.id===draft.json().id));assert.equal((await request('GET','/email/drafts',{},one.cookie)).statusCode,403);assert.equal((await request('PUT','/email/signatures',{mailbox:'mail',body:'Anil Bishnoi\nANIBISH'},admin.cookie)).statusCode,200);assert.equal((await request('GET','/email/signatures',{},one.cookie)).statusCode,403);assert.ok((await request('GET','/email/signatures',{},admin.cookie)).json().find((s:{mailbox:string;body:string})=>s.mailbox==='mail'&&s.body.includes('Anil Bishnoi')));assert.equal((await request('POST','/email/drafts',{mailbox:'mail',recipient:'qa@example.test',subject:'Unsafe filename',body:'Do not send.',extras:{cc:[],attachments:[{name:'../unsafe.txt',base64:'eA=='}]}},admin.cookie)).statusCode,400)});
test('email CRM conversion copies only explicit summaries and keeps original correspondence private',async()=>{const project=(await request('POST','/projects',{title:'Mail conversion isolation QA',org_id:one.me.org_id},admin.cookie)).json();const [mail]=(await pool.query("INSERT INTO mail_messages(mailbox,folder,uidvalidity,uid,subject,body_text) VALUES('info',$1,'1',1,'Private QA source','PRIVATE ORIGINAL MUST NOT BE COPIED') RETURNING id",['QA-'+randomUUID()])).rows;const payload={kind:'task',project_id:project.id,title:'Authorized internal follow-up',summary:'Explicitly approved summary for this task only.'};const task=await request('POST','/email/messages/'+mail.id+'/work-item',payload,admin.cookie);assert.equal(task.statusCode,200,task.body);const repeat=await request('POST','/email/messages/'+mail.id+'/work-item',payload,admin.cookie);assert.equal(repeat.json().id,task.json().id);const [row]=(await pool.query('SELECT * FROM tasks WHERE id=$1',[task.json().id])).rows;assert.equal(row.internal,true);assert.equal(row.description,payload.summary);assert.equal((await request('GET','/tasks',{},one.cookie)).json().some((t:{id:string})=>t.id===row.id),false);assert.equal((await request('POST','/email/messages/'+mail.id+'/work-item',{...payload,kind:'ticket'},one.cookie)).statusCode,403);const ticket=await request('POST','/email/messages/'+mail.id+'/work-item',{...payload,kind:'ticket'},admin.cookie);assert.equal(ticket.statusCode,200,ticket.body);assert.equal((await request('GET','/tickets/'+ticket.json().id,{},one.cookie)).json().body,payload.summary);assert.equal((await request('GET','/tickets/'+ticket.json().id,{},two.cookie)).statusCode,404);assert.equal((await request('GET','/email/messages/'+mail.id,{},one.cookie)).statusCode,403)});
test('review bulk publication enforces clearance atomically and denies customer access',async()=>{const id='qa-review-'+randomUUID(),blocked=id+'-blocked';await pool.query("INSERT INTO review_candidates(id,source_number,transcription) VALUES($1,9900,'Authentic QA fixture used only in the isolated test database.'),($2,9901,'Restricted QA fixture.')",[id,blocked]);assert.equal((await request('GET','/review-candidates',{},one.cookie)).statusCode,403);assert.equal((await request('POST','/review-candidates/batch',{ids:[id],action:'approve',confirmed:true},admin.cookie)).statusCode,409);await pool.query("UPDATE review_candidates SET privacy='cleared',clearance_note='Isolated QA fixture authorization',confidence='visually_verified' WHERE id=$1",[id]);assert.equal((await request('POST','/review-candidates/batch',{ids:[id,blocked],action:'approve',confirmed:true},admin.cookie)).statusCode,409);assert.equal((await pool.query('SELECT state FROM review_candidates WHERE id=$1',[id])).rows[0].state,'draft');assert.equal((await request('POST','/review-candidates/batch',{ids:[id],action:'approve',confirmed:true},admin.cookie)).statusCode,200);assert.equal((await request('POST','/review-candidates/batch',{ids:[id],action:'publish',confirmed:true},admin.cookie)).statusCode,200);assert.equal((await pool.query('SELECT state FROM cms_pages WHERE slug=$1',['historical-'+id])).rows[0].state,'published');assert.equal((await request('POST','/review-candidates/batch',{ids:[id],action:'unpublish',confirmed:true},admin.cookie)).statusCode,200);assert.equal((await pool.query('SELECT state FROM cms_pages WHERE slug=$1',['historical-'+id])).rows[0].state,'archived')});
test('Brevo callbacks authenticate, correlate, deduplicate and preserve terminal suppression',async()=>{const previous=process.env.ANIBISH_BREVO_WEBHOOK_TOKEN;process.env.ANIBISH_BREVO_WEBHOOK_TOKEN='qa-'+randomUUID()+randomUUID();try{const [job]=(await pool.query("INSERT INTO outbox(recipient,template,payload,status,delivery_id) VALUES($1,'welcome','{}','sent',$2) RETURNING id",[one.email,'<callback-'+randomUUID()+'@anibish.com>'])).rows;const payload={event:'delivered',email:one.email,'message-id':'provider-'+randomUUID(),'X-Mailin-custom':'anibish_outbox_id:'+job.id,ts_event:Math.floor(Date.now()/1000)};const callback=(data:unknown,authorized=true)=>app.inject({method:'POST',url:'/notifications/webhooks/brevo',headers:{'content-type':'application/json',...(authorized?{authorization:'Bearer '+process.env.ANIBISH_BREVO_WEBHOOK_TOKEN}:{})},payload:JSON.stringify(data)});assert.equal((await callback(payload,false)).statusCode,401);let r=await callback(payload);assert.equal(r.statusCode,200,r.body);assert.equal(r.json().accepted,1);r=await callback(payload);assert.equal(r.json().duplicates,1);assert.equal((await pool.query('SELECT delivery_status FROM outbox WHERE id=$1',[job.id])).rows[0].delivery_status,'delivered');assert.equal((await callback({...payload,event:'hard_bounce'})).json().accepted,1);assert.equal((await pool.query('SELECT active FROM mail_suppressions WHERE email=$1',[one.email])).rows[0].active,true);await callback({...payload,event:'request'});assert.equal((await pool.query('SELECT delivery_status FROM outbox WHERE id=$1',[job.id])).rows[0].delivery_status,'hard_bounce');assert.equal((await callback({...payload,email:two.email})).json().unmatched,1);assert.equal((await request('GET','/notification-operations',{},one.cookie)).statusCode,403);assert.equal((await request('POST','/notification-operations/'+job.id+'/retry',{confirmed:true},admin.cookie)).statusCode,409);await pool.query('UPDATE mail_suppressions SET active=false WHERE email=$1',[one.email]);}finally{if(previous===undefined)delete process.env.ANIBISH_BREVO_WEBHOOK_TOKEN;else process.env.ANIBISH_BREVO_WEBHOOK_TOKEN=previous}});
test('refund policies use the versioned owner editor and marketing consent is independent',async()=>{const drafts=await request('GET','/legal',{},admin.cookie);assert.ok(drafts.json().drafts.some((d:{policy:string})=>d.policy==='refunds'));assert.equal((await request('PUT','/legal/refunds',{html:'<p>Unauthorized policy mutation</p>',revision:1,effective_date:'2026-11-16'},one.cookie)).statusCode,403);assert.ok((await pool.query('SELECT 1 FROM marketing_consents WHERE user_id=$1 AND opted_in=false',[one.me.id])).rowCount);assert.equal((await request('POST','/legal/acceptance',{legal_acceptance:{accepted:false}},one.cookie)).statusCode,400)});
test('password changes revoke sessions, preserve preferences and queue security notification',async()=>{const u=await register('password-change');const next='Replacement-'+randomUUID();assert.equal((await request('POST','/auth/password',{current_password:'wrong-password',new_password:next},u.cookie)).statusCode,400);const changed=await request('POST','/auth/password',{current_password:password,new_password:next},u.cookie);assert.equal(changed.statusCode,200,changed.body);assert.equal((await request('GET','/auth/me',{},u.cookie)).statusCode,401);assert.equal((await request('POST','/auth/login',{email:u.email,password},'')).statusCode,401);const login=await request('POST','/auth/login',{email:u.email,password:next});assert.equal(login.statusCode,200,login.body);const cookie=login.headers['set-cookie'] as string;assert.equal((await request('PATCH','/auth/profile',{name:'Updated QA',preferences:{email_updates:false,marketing_opt_in:true}},cookie)).statusCode,200);assert.equal((await request('PATCH','/auth/profile',{name:'Updated QA Again',preferences:{email_updates:true}},cookie)).statusCode,200);const user=(await request('GET','/auth/me',{},cookie)).json().user;assert.equal(user.preferences.marketing_opt_in,true);assert.ok((await pool.query("SELECT 1 FROM marketing_consents WHERE user_id=$1 AND opted_in=true AND workflow='account_settings'",[u.me.id])).rowCount);assert.ok((await pool.query("SELECT 1 FROM outbox WHERE recipient=$1 AND template='password_changed'",[u.email])).rowCount)});
test('mail retention, thread history and template operations require privileged MFA',async()=>{for(const path of ['/email/retention','/email/threads','/notification-templates'])assert.equal((await request('GET',path,{},one.cookie)).statusCode,403);assert.equal((await request('PUT','/email/retention',{cache_days:30,confirmed_cache_only:false},admin.cookie)).statusCode,400);assert.equal((await request('PUT','/email/retention',{cache_days:0,confirmed_cache_only:true},admin.cookie)).statusCode,200);const key='welcome';const preview=await request('POST','/notification-templates/'+key+'/preview',{subject:'QA draft',body:'This isolated QA template is not sent.'},admin.cookie);assert.equal(preview.statusCode,200,preview.body);assert.ok(preview.json().html.includes('QA draft'));assert.equal((await request('PUT','/notification-templates/not-a-template',{subject:'Bad',body:'Not supported'},admin.cookie)).statusCode,400)});

test('mail history resumes beyond 100 with sparse UIDs and preserves deleted-message history',async()=>{const {syncMailbox}=await import('../mail-centre');const folder='history-'+randomUUID();let uids=Array.from({length:155},(_,i)=>1000+i*3),uidOptions=true;const fake={mailbox:{uidValidity:777},getMailboxLock:async()=>({release(){}}),search:async()=>uids,fetchAll:async(range:string,_query:unknown,opts:{uid?:boolean})=>{uidOptions&&=opts?.uid===true;return range.split(',').map(Number).filter(uid=>uids.includes(uid)).map(uid=>({uid,size:200,flags:new Set(['\\Seen'])}))},fetchOne:async(uid:number,_q:unknown,opts:{uid?:boolean})=>{uidOptions&&=opts?.uid===true;return {source:Buffer.from('From: fixture@example.test\r\nTo: info@anibish.com\r\nMessage-ID: <history-'+folder+'-'+uid+'@example.test>\r\nSubject: Historical fixture '+uid+'\r\n\r\nPersisted history body')}}};const transport=(async(_account:string,action:(client:unknown)=>Promise<unknown>)=>action(fake)) as Parameters<typeof syncMailbox>[2];let r=await syncMailbox('info',folder,transport);assert.equal(r.synced,100);assert.equal(r.remaining,55);r=await syncMailbox('info',folder,transport);assert.equal(r.synced,55);assert.equal(r.remaining,0);r=await syncMailbox('info',folder,transport);assert.equal(r.synced,0);uids=uids.slice(1);await syncMailbox('info',folder,transport);assert.equal((await pool.query('SELECT count(*)::int AS count FROM mail_messages WHERE folder=$1',[folder])).rows[0].count,155);assert.equal((await pool.query('SELECT count(*)::int AS count FROM mail_messages WHERE folder=$1 AND active',[folder])).rows[0].count,154);assert.equal(uidOptions,true);await pool.query('DELETE FROM mail_messages WHERE folder=$1',[folder]);await pool.query('DELETE FROM mail_sync_state WHERE folder=$1',[folder])});
test('linked correspondence history remains owner-private and preserves explicit source references',async()=>{const project=(await request('POST','/projects',{title:'Correspondence QA',org_id:one.me.org_id},admin.cookie)).json();const [mail]=(await pool.query("INSERT INTO mail_messages(mailbox,folder,uidvalidity,uid,subject) VALUES('info',$1,'1',1,'Private correspondence QA') RETURNING id",['correspondence-'+randomUUID()])).rows;const link=await request('POST','/email/messages/'+mail.id+'/link',{kind:'project',resource_id:project.id},admin.cookie);assert.equal(link.statusCode,200,link.body);const path='/email/correspondence?kind=project&resource_id='+project.id;assert.equal((await request('GET',path,{},one.cookie)).statusCode,403);assert.equal((await request('GET',path,{},two.cookie)).statusCode,403);const rows=(await request('GET',path,{},admin.cookie)).json();assert.equal(rows.length,1);assert.equal(rows[0].id,mail.id);assert.equal(rows[0].subject,'Private correspondence QA')});

test('MFA recovery codes require password and TOTP, are hashed and can be used only once',async()=>{const login=(payload:unknown)=>app.inject({method:'POST',url:'/auth/login',remoteAddress:'127.234.1.1',headers:{...headers,'content-type':'application/json'},payload:JSON.stringify(payload)});assert.equal((await request('GET','/auth/mfa/recovery',{},one.cookie)).statusCode,403);assert.equal((await request('POST','/auth/mfa/recovery',{password:'incorrect',code:totp(adminSecret),replace_existing:true},admin.cookie)).statusCode,403);const r=await request('POST','/auth/mfa/recovery',{password,code:totp(adminSecret),replace_existing:true},admin.cookie);assert.equal(r.statusCode,200,r.body);const codes=r.json().codes;assert.equal(codes.length,8);const stored=(await pool.query('SELECT code_hash FROM mfa_recovery_codes WHERE user_id=$1',[admin.me.id])).rows;assert.equal(stored.length,8);assert.ok(stored.every(r=>!codes.includes(r.code_hash)&&r.code_hash.length===64));const logins=await Promise.all([login({email:admin.email,password,recovery_code:codes[0]}),login({email:admin.email,password,recovery_code:codes[0]})]);assert.deepEqual(logins.map(r=>r.statusCode).sort(),[200,403]);assert.equal((await request('GET','/auth/mfa/recovery',{},admin.cookie)).json().remaining,7);assert.equal((await login({email:admin.email,password,code:totp(adminSecret)})).statusCode,200)});
test('project, milestone and support events use their configured transactional templates',async()=>{const title='Canonical event '+randomUUID();const createdProject=await request('POST','/projects',{title,org_id:one.me.org_id},admin.cookie);assert.equal(createdProject.statusCode,200,createdProject.body);const project=createdProject.json();const createdMilestone=await request('POST','/milestones',{title:title+' milestone',project_id:project.id},admin.cookie);assert.equal(createdMilestone.statusCode,200,createdMilestone.body);const milestone=createdMilestone.json();{const update=await request('PATCH','/milestones/'+milestone.id,{status:'completed'},admin.cookie);assert.equal(update.statusCode,200,update.body)}{const update=await request('PATCH','/milestones/'+milestone.id,{status:'completed'},admin.cookie);assert.equal(update.statusCode,200,update.body)}const ticket=(await request('POST','/tickets',{title:title+' support',body:'Synthetic support notification test.'},one.cookie)).json();await request('POST','/tickets/'+ticket.id+'/replies',{body:'Synthetic studio response.'},admin.cookie);const rows=(await pool.query("SELECT template,count(*)::int AS count FROM outbox WHERE recipient=$1 AND payload->>'body' LIKE $2 GROUP BY template",[one.email,title+'%'])).rows;for(const key of ['project_created','milestones.created','milestone_completed','ticket_created','ticket_updated'])assert.ok(rows.some(r=>r.template===key),key);assert.equal(rows.find(r=>r.template==='milestone_completed').count,1)});
test('two distinct occurrences from one review source can publish without duplicating legacy excerpts',async()=>{const root='qa-occurrence-'+randomUUID(),ids=[root+'-1',root+'-2'];for(const id of ids)await pool.query("INSERT INTO review_candidates(id,source_number,occurrence,transcription,confidence,privacy,clearance_note,state) VALUES($1,9999,$2,'Synthetic distinct occurrence fixture.','visually_verified','cleared','Isolated QA fixture authorization','approved')",[id,id.endsWith('-1')?1:2]);const r=await request('POST','/review-candidates/batch',{ids,action:'publish',confirmed:true},admin.cookie);assert.equal(r.statusCode,200,r.body);assert.equal((await pool.query("SELECT count(*)::int AS count FROM cms_pages WHERE slug=ANY($1::text[]) AND state='published'",[ids.map(id=>'historical-'+id)])).rows[0].count,2);await request('POST','/review-candidates/batch',{ids,action:'unpublish',confirmed:true},admin.cookie)});

test('quotation consent records retain accepted policy versions and the engagement reference',async()=>{const {acceptLegal}=await import('../legal');const db=await pool.connect();try{await db.query('BEGIN');const policies=(await db.query("SELECT DISTINCT ON(v.policy) v.id,v.policy FROM legal_versions v JOIN legal_policy_state s ON s.policy=v.policy AND s.enabled WHERE v.policy IN('privacy','terms') AND v.effective_date<=CURRENT_DATE ORDER BY v.policy,v.version DESC")).rows;assert.equal(policies.length,2);const legal_acceptance={accepted:true,...Object.fromEntries(policies.map(v=>[v.policy,v.id]))};await acceptLegal(db,{legal_acceptance},one.me.id,'registration',undefined,true);const reference=randomUUID();await acceptLegal(db,{accepted_scope:true},one.me.id,'quotation',reference,true);const rows=(await db.query("SELECT policy_version_id FROM legal_consents WHERE user_id=$1 AND workflow='quotation' AND reference_id=$2",[one.me.id,reference])).rows;assert.equal(rows.length,2);assert.ok(rows.every(r=>policies.some(p=>p.id===r.policy_version_id)));await db.query('ROLLBACK')}finally{db.release()}});
test('older published review snapshots gain identities without changing their text',async()=>{const {readFile}=await import('node:fs/promises'),root='qa-backfill-'+randomUUID(),ids=[root+'-1',root+'-2'];for(const [i,id] of ids.entries())await pool.query("INSERT INTO review_candidates(id,source_number,occurrence,transcription,confidence,privacy,clearance_note,state) VALUES($1,9998,$2,'Synthetic review identity upgrade fixture.','visually_verified','cleared','Isolated QA fixture authorization','approved')",[id,i+1]);assert.equal((await request('POST','/review-candidates/batch',{ids:[ids[0]],action:'publish',confirmed:true},admin.cookie)).statusCode,200);await pool.query("UPDATE cms_pages SET content=content-'candidate_id'-'occurrence',published_content=published_content-'candidate_id'-'occurrence' WHERE slug=$1",['historical-'+ids[0]]);await pool.query(await readFile(new URL('../migrations/024_review_identity_backfill.sql',import.meta.url),'utf8'));const row=(await pool.query('SELECT content FROM cms_pages WHERE slug=$1',['historical-'+ids[0]])).rows[0];assert.equal(row.content.candidate_id,ids[0]);assert.equal(row.content.body,'Synthetic review identity upgrade fixture.');const published=await request('POST','/review-candidates/batch',{ids,action:'publish',confirmed:true},admin.cookie);assert.equal(published.statusCode,200,published.body);await request('POST','/review-candidates/batch',{ids,action:'unpublish',confirmed:true},admin.cookie)});

test('customers cannot read administrative catalogue, evidence metadata, team, audit or delivery queues',async()=>{for(const route of ['/admin/services','/admin/assets','/admin/team','/admin/audit','/admin/outbox']){assert.equal((await request('GET',route,{},one.cookie)).statusCode,403,route);assert.equal((await request('GET',route,{},two.cookie)).statusCode,403,route);assert.equal((await request('GET',route)).statusCode,401,route)}assert.equal((await request('GET','/admin/services',{},admin.cookie)).statusCode,200)});

test('portfolio evidence imports are MFA-owner-only, idempotent and preserve owner clearance',async()=>{assert.equal((await request('GET','/portfolio-sources',{},one.cookie)).statusCode,403);const payload={records:[{provider:'fiverr',external_key:'qa-source-'+suffix,title:'Private QA delivery',facts:{scope:'Private documented scope'}}]};const first=await request('POST','/portfolio-sources/import',payload,admin.cookie);assert.equal(first.statusCode,200,first.body);assert.equal(first.json().added,1);assert.equal((await request('POST','/portfolio-sources/import',payload,admin.cookie)).json().unchanged,1);const row=(await request('GET','/portfolio-sources',{},admin.cookie)).json().find((r:{external_key:string})=>r.external_key==='qa-source-'+suffix);await request('PATCH','/portfolio-sources/'+row.id,{clearance:'restricted',owner_notes:'Do not publish private requirements',page_id:null},admin.cookie);payload.records[0].facts.scope='Updated private evidence';assert.equal((await request('POST','/portfolio-sources/import',payload,admin.cookie)).json().changed,1);const updated=(await request('GET','/portfolio-sources',{},admin.cookie)).json().find((r:{id:string})=>r.id===row.id);assert.equal(updated.clearance,'restricted');assert.equal(updated.owner_notes,'Do not publish private requirements');assert.equal((await request('GET','/public/site')).body.includes('Updated private evidence'),false)});

test('published portfolio foundation has meaningful cited content and private source routes remain isolated',async()=>{const site=(await request('GET','/public/site')).json();const projects=site.pages.filter((p:{kind:string})=>p.kind==='portfolio');assert.ok(projects.length>=9);const v=projects.find((p:{slug:string})=>p.slug==='portfolio/vchalk-education');assert.ok(v);assert.match(v.content.role,/Co-Founder/);assert.ok(v.content.sources.length>=3);assert.match(v.content.body,/does not|do not|not imply/);assert.equal(site.pages.filter((p:{kind:string})=>p.kind==='award').length,6);for(const u of [one,two])assert.equal((await request('POST','/portfolio-sources/import',{records:[]},u.cookie)).statusCode,403)});

test('private source imports group related records into unpublished drafts without overwriting manual edits',async()=>{const slug='portfolio/qa-group-'+suffix,portfolio_draft={slug,title:'Private grouped engagement QA',content:{description:'Private source-backed draft, pending rights review.',body:'Initial curated draft.',category:'Freelance Client Projects'}};const records=[{provider:'fiverr',external_key:'qa-group-one-'+suffix,title:'First related order',facts:{scope:'First private scope'},portfolio_draft},{provider:'fiverr',external_key:'qa-group-two-'+suffix,title:'Second related order',facts:{scope:'Second private scope'},portfolio_draft}];const imported=await request('POST','/portfolio-sources/import',{records},admin.cookie);assert.equal(imported.statusCode,200,imported.body);assert.equal(imported.json().drafts_created,1);const p=(await pool.query('SELECT * FROM cms_pages WHERE slug=$1',[slug])).rows[0];assert.equal(p.state,'draft');assert.equal(p.content.evidence_attested,false);assert.equal((await request('POST','/cms/pages/'+p.id+'/publish',{expected_revision:p.revision},admin.cookie)).statusCode,400);assert.equal((await pool.query('SELECT count(*) FROM portfolio_sources WHERE page_id=$1',[p.id])).rows[0].count,'2');assert.equal((await request('GET','/public/site')).body.includes('Private grouped engagement QA'),false);await pool.query("UPDATE cms_pages SET content=jsonb_set(content,'{body}','\"Owner manual edit\"') WHERE id=$1",[p.id]);records[0].facts.scope='Updated source';records[0].portfolio_draft.content.body='Must not overwrite owner';await request('POST','/portfolio-sources/import',{records},admin.cookie);assert.equal((await pool.query('SELECT content FROM cms_pages WHERE id=$1',[p.id])).rows[0].content.body,'Owner manual edit')});

test('quote and invoice business events enqueue atomically once across repeated decisions',async()=>{const title='Transactional events '+suffix;const quote=(await request('POST','/quotes',{org_id:one.me.org_id,title,currency:'INR',lines:[{description:'Sandbox event test',quantity:1,unit_amount:0}],terms:'Disposable sandbox scope.',status:'sent'},admin.cookie)).json();const responses=await Promise.all([request('POST','/quotes/'+quote.id+'/decision',{decision:'accepted',accepted_scope:true},one.cookie),request('POST','/quotes/'+quote.id+'/decision',{decision:'accepted',accepted_scope:true},one.cookie)]);for(const r of responses)assert.equal(r.statusCode,200,r.body);const order=responses[0].json().order;for(const template of ['quote_decision','order_confirmation','project_created']){const rows=(await pool.query('SELECT count(*) FROM outbox WHERE recipient=$1 AND template=$2 AND payload->>\'body\'=$3',[one.email,template,title])).rows;assert.equal(rows[0].count,'1',template)}assert.equal((await request('POST','/quotes/'+quote.id+'/decision',{decision:'rejected'},one.cookie)).statusCode,409);const invoice=(await request('POST','/finance/invoices',{order_id:order.id,lines:[{description:'Sandbox only',quantity:1,unit_amount:0}],tax_rate_bps:0,discount:0,deposit_applied:0,due_date:'2026-12-01',kind:'milestone'},admin.cookie)).json();for(let i=0;i<2;i++){const r=await request('POST','/finance/invoices/'+invoice.id+'/finalize',{},admin.cookie);assert.equal(r.statusCode,200,r.body)}assert.equal((await pool.query('SELECT count(*) FROM outbox WHERE recipient=$1 AND dedupe_key=$2',[one.email,'invoice:'+invoice.id+':finalized:'+one.email])).rows[0].count,'1')});

test('private email drafts update once, reject stale editors and archive reversibly without sending',async()=>{const before=(await pool.query('SELECT count(*) FROM mail_sends')).rows[0].count;const payload={mailbox:'mail',recipient:'draft-only@example.test',subject:'Editable draft '+suffix,body:'Never send this private QA draft.',extras:{cc:[],attachments:[]}};const created=await request('POST','/email/drafts',payload,admin.cookie);assert.equal(created.statusCode,200,created.body);const d=created.json();const updated=await request('PUT','/email/drafts/'+d.id,{...payload,body:'Updated private draft.',expected_updated_at:d.updated_at},admin.cookie);assert.equal(updated.statusCode,200,updated.body);assert.equal(updated.json().id,d.id);assert.equal((await request('PUT','/email/drafts/'+d.id,{...payload,expected_updated_at:d.updated_at},admin.cookie)).statusCode,409);assert.equal((await request('PUT','/email/drafts/'+d.id,{...payload,expected_updated_at:updated.json().updated_at},one.cookie)).statusCode,403);assert.equal((await request('POST','/email/drafts/'+d.id+'/archive',{},admin.cookie)).statusCode,200);assert.equal((await request('GET','/email/drafts',{},admin.cookie)).json().some((x:{id:string})=>x.id===d.id),false);assert.ok((await request('GET','/email/drafts?archived=true',{},admin.cookie)).json().some((x:{id:string})=>x.id===d.id));assert.equal((await request('POST','/email/drafts/'+d.id+'/restore',{},admin.cookie)).statusCode,200);assert.ok((await request('GET','/email/drafts',{},admin.cookie)).json().some((x:{id:string})=>x.id===d.id));assert.equal((await pool.query('SELECT count(*) FROM mail_sends')).rows[0].count,before)});

test('legacy case-study routes retain source-backed CMS records and review associations',async()=>{const pages=(await request('GET','/public/site')).json().pages;for(const slug of ['ssl-scanner','responsive-websites']){const p=pages.find((x:{slug:string})=>x.slug==='portfolio/'+slug);assert.ok(p,slug);assert.equal(p.kind,'portfolio');assert.ok(p.content.body.length>200);assert.ok(p.content.sources.some((s:{url:string})=>s.url==='https://anibish.com/reviews'))}});

test('accepted quotation replays do not append duplicate production consent records',async()=>{const policies=(await request('GET','/public/legal')).json();const legal_acceptance={accepted:true,...Object.fromEntries(policies.filter((p:{policy:string})=>['privacy','terms'].includes(p.policy)).map((p:{policy:string;id:string})=>[p.policy,p.id]))};const quote=(await request('POST','/quotes',{org_id:one.me.org_id,title:'Consent replay '+suffix,currency:'INR',lines:[{description:'Consent replay QA',quantity:1,unit_amount:0}],terms:'Sandbox scope only.',status:'sent'},admin.cookie)).json();const oldEnv=process.env.NODE_ENV,oldStage=process.env.LAUNCH_STAGE;try{process.env.NODE_ENV='production';process.env.LAUNCH_STAGE='full';for(let i=0;i<2;i++){const r=await request('POST','/quotes/'+quote.id+'/decision',{decision:'accepted',accepted_scope:true,legal_acceptance},one.cookie);assert.equal(r.statusCode,200,r.body)}assert.equal((await pool.query("SELECT count(*) FROM legal_consents WHERE user_id=$1 AND workflow='quotation' AND reference_id=$2",[one.me.id,quote.id])).rows[0].count,'2')}finally{if(oldEnv===undefined)delete process.env.NODE_ENV;else process.env.NODE_ENV=oldEnv;if(oldStage===undefined)delete process.env.LAUNCH_STAGE;else process.env.LAUNCH_STAGE=oldStage}});

test('private draft creation replays safely after lost responses and refuses conflicting content',async()=>{const idempotency_key=randomUUID(),payload={mailbox:'mail',recipient:'draft-only@example.test',subject:'Idempotent draft '+suffix,body:'Private draft only; do not send.',extras:{cc:[],attachments:[]},idempotency_key};const results=await Promise.all([request('POST','/email/drafts',payload,admin.cookie),request('POST','/email/drafts',payload,admin.cookie)]);for(const r of results)assert.equal(r.statusCode,200,r.body);assert.equal(results[0].json().id,results[1].json().id);assert.equal((await pool.query('SELECT count(*) FROM mail_drafts WHERE id=$1',[idempotency_key])).rows[0].count,'1');assert.equal((await request('POST','/email/drafts',{...payload,body:'Different unsaved content'},admin.cookie)).statusCode,409);assert.equal((await pool.query('SELECT body FROM mail_drafts WHERE id=$1',[idempotency_key])).rows[0].body,payload.body)});

test('billing profiles are organization-scoped, role protected and reject stale edits',async()=>{const data={legal_name:'Synthetic QA billing identity',billing_email:'billing@example.test',address:'Synthetic test address',country:'Test country',tax_reference:''};const a=await request('GET','/account/billing-profile',{},one.cookie),b=await request('GET','/account/billing-profile',{},two.cookie);assert.equal(a.statusCode,200,a.body);assert.equal(b.statusCode,200,b.body);const saved=await request('PUT','/account/billing-profile',{data,expected_revision:a.json().revision},one.cookie);assert.equal(saved.statusCode,200,saved.body);assert.equal((await request('GET','/account/billing-profile',{},two.cookie)).json().data.legal_name,b.json().data.legal_name);assert.equal((await request('PUT','/account/billing-profile',{data,expected_revision:a.json().revision},one.cookie)).statusCode,409);assert.equal((await request('PUT','/account/billing-profile',{data,expected_revision:saved.json().revision,org_id:two.me.org_id},one.cookie)).statusCode,400);await pool.query("UPDATE memberships SET role='viewer' WHERE user_id=$1 AND org_id=$2",[one.me.id,one.me.org_id]);try{assert.equal((await request('PUT','/account/billing-profile',{data,expected_revision:saved.json().revision},one.cookie)).statusCode,403)}finally{await pool.query("UPDATE memberships SET role='owner' WHERE user_id=$1 AND org_id=$2",[one.me.id,one.me.org_id])}assert.equal((await request('GET','/account/billing-profile',{},admin.cookie)).statusCode,403)});

test('customer deactivation revokes sessions and recovery without deleting consent or MFA',async()=>{const u=await register('deactivation',testAddress.replace('127.0.','127.2.')),second=await request('POST','/auth/login',{email:u.email,password},'',testAddress.replace('127.0.','127.2.'));const recovery=(await request('POST','/auth/recover',{email:u.email})).json().development_link,raw=new URL('http://localhost'+recovery).searchParams.get('token');const setup=(await request('POST','/auth/mfa/setup',{},u.cookie,testAddress.replace('127.0.','127.2.'))).json();assert.equal((await request('POST','/auth/mfa/verify',{code:totp(setup.secret)},u.cookie,testAddress.replace('127.0.','127.2.'))).statusCode,200);assert.equal((await request('POST','/auth/deactivate',{password:'incorrect',confirmed:true,code:totp(setup.secret)},u.cookie,testAddress.replace('127.0.','127.2.'))).statusCode,403);assert.equal((await request('POST','/auth/deactivate',{password,confirmed:true},u.cookie,testAddress.replace('127.0.','127.2.'))).statusCode,403);assert.equal((await request('POST','/auth/deactivate',{password,confirmed:true,code:totp(adminSecret)},admin.cookie,testAddress.replace('127.0.','127.3.'))).statusCode,403);const before=(await pool.query('SELECT count(*) FROM marketing_consents WHERE user_id=$1',[u.me.id])).rows[0].count;const r=await request('POST','/auth/deactivate',{password,confirmed:true,code:totp(setup.secret)},u.cookie,testAddress.replace('127.0.','127.2.'));assert.equal(r.statusCode,200,r.body);for(const cookie of [u.cookie,second.headers['set-cookie'] as string])assert.equal((await request('GET','/auth/me',{},cookie)).statusCode,401);assert.equal((await request('POST','/auth/login',{email:u.email,password,code:totp(setup.secret)},'',testAddress.replace('127.0.','127.2.'))).statusCode,401);assert.equal((await request('POST','/auth/token',{token:raw,password})).statusCode,400);assert.equal((await request('POST','/auth/recover',{email:u.email})).json().development_link,undefined);const record=(await pool.query('SELECT disabled_at,mfa_enabled FROM users WHERE id=$1',[u.me.id])).rows[0];assert.ok(record.disabled_at);assert.equal(record.mfa_enabled,true);assert.equal((await pool.query('SELECT count(*) FROM marketing_consents WHERE user_id=$1',[u.me.id])).rows[0].count,before);assert.equal((await pool.query("SELECT count(*) FROM audit_log WHERE actor_id=$1 AND action='account.deactivated'",[u.me.id])).rows[0].count,'1')});

test('closure requests are idempotent and sole owners cannot strand active organization members',async()=>{const u=await register('closure-owner',testAddress.replace('127.0.','127.4.'));await pool.query("INSERT INTO memberships(user_id,org_id,role) VALUES($1,$2,'member')",[two.me.id,u.me.org_id]);for(let i=0;i<2;i++)assert.equal((await request('POST','/auth/closure',{},u.cookie)).statusCode,200);assert.equal((await pool.query("SELECT count(*) FROM records WHERE created_by=$1 AND kind='closure' AND status='requested'",[u.me.id])).rows[0].count,'1');assert.equal((await request('POST','/auth/deactivate',{password,confirmed:true},u.cookie)).statusCode,409);assert.equal((await request('GET','/auth/me',{},u.cookie)).statusCode,200);await pool.query('DELETE FROM memberships WHERE user_id=$1 AND org_id=$2',[two.me.id,u.me.org_id])});

test('invitation retries normalize identity and enqueue exactly once without replacing the original token',async()=>{const idempotency_key=randomUUID(),email=two.email,payload={email:email.toUpperCase(),role:'member',idempotency_key};const results=await Promise.all([request('POST','/invitations',payload,one.cookie),request('POST','/invitations',payload,one.cookie)]);for(const r of results)assert.equal(r.statusCode,200,r.body);assert.equal(results[0].json().id,results[1].json().id);assert.equal((await pool.query("SELECT count(*) FROM records WHERE org_id=$1 AND kind='invitation' AND data->>'idempotency_key'=$2",[one.me.org_id,idempotency_key])).rows[0].count,'1');assert.equal((await pool.query("SELECT count(*) FROM outbox WHERE recipient=$1 AND template='organization_invitation'",[email])).rows[0].count,'1');assert.equal((await request('POST','/invitations',{...payload,role:'owner'},one.cookie)).statusCode,409);const original=results.map(r=>r.json()).find(r=>r.development_token);assert.ok(original);await pool.query('UPDATE records SET title=upper(title) WHERE id=$1',[original.id]);assert.equal((await request('POST','/invitations/accept',{token:original.development_token},one.cookie)).statusCode,400);assert.equal((await request('POST','/invitations/accept',{token:original.development_token},two.cookie)).statusCode,200);assert.equal((await request('POST','/invitations/accept',{token:original.development_token},two.cookie)).statusCode,400)});

test('approved public products seed meaningful cases without replacing owner edits',async()=>{const slugs=['portfolio/10learn','portfolio/bharat-mega-mall','portfolio/bishnoi-pro','portfolio/carswhere'];const pages=(await request('GET','/public/site')).json().pages;for(const slug of slugs){const page=pages.find((p:{slug:string})=>p.slug===slug);assert.ok(page,slug);assert.ok(page.content.body.length>200);assert.ok(page.content.features.length>=3);assert.ok(page.content.role&&page.content.project_status);assert.equal(page.content.evidence_attested,true);assert.equal(JSON.stringify(page.content).includes('github.com/anibish/'),false)}const db=await pool.connect();try{await db.query('BEGIN');await db.query("UPDATE cms_pages SET content=jsonb_set(content,'{body}','\"Owner manual change\"'),revision=revision+1 WHERE slug=$1",[slugs[0]]);const {readFile}=await import('node:fs/promises');await db.query(await readFile(new URL('../migrations/030_approved_public_products.sql',import.meta.url),'utf8'));assert.equal((await db.query('SELECT content FROM cms_pages WHERE slug=$1',[slugs[0]])).rows[0].content.body,'Owner manual change');await db.query('ROLLBACK')}finally{db.release()}});

test('six remaining approved product seeds recover fresh content and preserve all owner publication states',async()=>{
 const slugs=['portfolio/civilpro','portfolio/estiva','portfolio/gadgetswhere','portfolio/local-ai-audio-tools','portfolio/origin-dating','portfolio/social6'];
 const pages=(await request('GET','/public/site')).json().pages;
 for(const slug of slugs){
  const page=pages.find((p:{slug:string})=>p.slug===slug);
  assert.ok(page,slug);assert.ok(page.content.body.length>200);assert.ok(page.content.features.length>=3);
  assert.ok(page.content.role&&page.content.project_status);assert.equal(page.content.evidence_attested,true);
  assert.equal(page.seo.canonical,'https://anibish.com/'+slug);
  assert.doesNotMatch(JSON.stringify(page.content),/github\.com|postgresql:\/\/|localhost|\.local\/|source_facts|order_id|baseline_content_sha256/i);
  for(const source of page.content.sources)assert.ok(['https://estiva.in/','https://gadgetswhere.com/'].includes(source.url));
 }
 const {readFile}=await import('node:fs/promises');
 const migration=await readFile(new URL('../migrations/031_remaining_approved_public_products.sql',import.meta.url),'utf8');
 const db=await pool.connect();
 try{
  await db.query('BEGIN');
  // A temporary copy exercises recovery from empty CMS storage without modifying the shared QA records.
  await db.query('CREATE TEMP TABLE cms_pages (LIKE public.cms_pages INCLUDING ALL) ON COMMIT DROP');
  await db.query('SET LOCAL search_path=pg_temp,public');
  await db.query(migration);
  const fresh=(await db.query('SELECT * FROM cms_pages ORDER BY slug')).rows;
  assert.deepEqual(fresh.map(p=>p.slug),slugs);
  for(const row of fresh){assert.equal(row.state,'published');assert.equal(row.revision,1);assert.deepEqual(row.published_content,row.content);assert.deepEqual(row.published_seo,row.seo);assert.ok(row.published_at)}
  await db.query(migration);
  assert.deepEqual((await db.query('SELECT * FROM cms_pages ORDER BY slug')).rows,fresh,'Fresh recovery replay must retain IDs, revisions and snapshots.');
  // Reimports must respect owners who edited, unpublished or archived an approved seed later.
  for(const [i,slug] of slugs.entries())await db.query("UPDATE cms_pages SET title=$1,state=$2,content=$3,published_content=$4,seo=$5,published_seo=$6,revision=$7,updated_at='2027-01-02T03:04:05Z',published_at=$8 WHERE slug=$9",[
   'Owner-edited '+slug,['draft','published','archived'][i%3],{body:'Owner working copy '+i,media_ids:[randomUUID()]},{body:'Owner prior public copy '+i},{title:'Owner draft SEO '+i},{title:'Owner published SEO '+i},17+i,i%3===0?null:'2026-11-16T00:00:00Z',slug
  ]);
  const edited=(await db.query('SELECT * FROM cms_pages ORDER BY slug')).rows;
  await db.query(migration);
  assert.deepEqual((await db.query('SELECT * FROM cms_pages ORDER BY slug')).rows,edited,'Recovery must never republish or overwrite owner edits.');
 }finally{await db.query('ROLLBACK');db.release()}
});
